import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {probes} from './probes.mjs';
const [suite='css',kind='normal',mode='timing']=process.argv.slice(2);
const root=new URL('../',import.meta.url).pathname;
const {makeRunner,fixtureInfo}=await import('./'+suite+'-cases.mjs');
const pressure=kind==='pressure';const variants=[0,1,2];const runners=[];
for(const variant of variants)runners.push(await makeRunner(variant,pressure));
const cases=Object.keys(fixtureInfo),rounds=12,calibrationGroups=3;
const guard=root+'tmp/guard-'+process.pid;await fs.writeFile(guard,Buffer.alloc(4096));
const median=v=>{const a=[...v].sort((a,b)=>a-b);return(a[(a.length-1)>>1]+a[a.length>>1])/2;};
function interval(v){let state=123456789;const rand=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};const a=Array.from({length:10000},()=>median(v.map(()=>v[Math.floor(rand()*v.length)]))).sort((a,b)=>a-b);const q=p=>{const x=p*(a.length-1),lo=Math.floor(x);return a[lo]+(a[Math.ceil(x)]-a[lo])*(x-lo);};return{median:median(v),interval95:[q(.025),q(.975)]};}
const protocol={suite,kind,mode,node:process.version,rounds,calibrationGroups,minimumQualifyingRounds:8,samplesPerVariant:2,noise:'Whole triplet exclusion on any CPU/IO probe above 1.5x median of three calibration group maxima.',control:'95% paired control interval contains zero and fits within +/-5%. Both candidate effects must agree.',bootstrapSamples:10000,seed:123456789,oldSpaceMiB:128,semiSpaceMiB:4,fixtureInfo,variants:['regexp','scanner','identical-scanner-control']};
const startedAt=new Date().toISOString();let calibration=[],samples=[];
function maxima(rows){assert.equal(rows.length,6);return Object.fromEntries(['cpuMs','ioMs'].map(m=>[m,Math.max(...rows.flatMap(r=>[r.noiseBefore[m],r.noiseAfter[m]]))]));}
try{
 for(const key of cases)for(const runner of runners)await runner.warm(key);
 if(mode==='profile'){
  for(let round=0;round<3;round++)for(let k=0;k<3;k++){
   const variant=(k+round)%3;
   for(const key of cases)samples.push({...await runners[variant].profile(key,root+`profiles/${suite}-${kind}-r${round}-v${variant}-${key}`),round,variant});
  }
  for(const key of cases)assert.equal(new Set(samples.filter(x=>x.case===key).map(x=>x.sha256)).size,1);
  await fs.writeFile(root+`runs/${suite}-${kind}-profile.json`,JSON.stringify({protocol,startedAt,finishedAt:new Date().toISOString(),samples},null,2));
 }else{
  for(let round=0;round<3+rounds;round++){
   const order=[0,1,2];order.push(...order.splice(0,round%3));if(round%2)order.reverse();
   for(const key of cases)for(const variant of order)for(let sample=0;sample<2;sample++){
    const noiseBefore=await probes(guard);const result=await runners[variant].sample(key);const noiseAfter=await probes(guard);
    (round<3?calibration:samples).push({...result,noiseBefore,noiseAfter,variant,round:round<3?round:round-3,sample});
   }
   process.stderr.write(`${suite} ${kind} ${round+1}/15\n`);
  }
  const thresholds=Object.fromEntries(cases.map(key=>[key,Object.fromEntries(['cpuMs','ioMs'].map(m=>[m,1.5*median(Array.from({length:3},(_,round)=>maxima(calibration.filter(x=>x.case===key&&x.round===round))[m]))]))]));
  const comparisons=[];
  for(const key of cases){
   const rows=samples.filter(x=>x.case===key);assert.equal(new Set([...rows,...calibration.filter(x=>x.case===key)].map(x=>x.sha256)).size,1);
   const excluded=[],accepted=[];
   for(let round=0;round<rounds;round++){const mx=maxima(rows.filter(x=>x.round===round));const metrics=Object.keys(mx).filter(m=>mx[m]>thresholds[key][m]);if(metrics.length)excluded.push({round,metrics});else accepted.push(round);}
   const c={case:key,acceptedRounds:accepted.length,excluded,status:'insufficient-rounds'};
   if(accepted.length>=8){
    const values=accepted.map(round=>variants.map(variant=>median(rows.filter(x=>x.round===round&&x.variant===variant).map(x=>x.totalMs))));
    c.effect=interval(values.map(x=>100*(x[1]/x[0]-1)));c.effectControl=interval(values.map(x=>100*(x[2]/x[0]-1)));c.control=interval(values.map(x=>100*(x[2]/x[1]-1)));c.medianMs=variants.map(v=>median(values.map(x=>x[v])));
    const [lo,hi]=c.control.interval95;c.status=!(lo<=0&&hi>=0&&lo>=-5&&hi<=5)?'unresolved-control':c.effect.interval95[1]<0&&c.effectControl.interval95[1]<0?'faster':c.effect.interval95[0]>0&&c.effectControl.interval95[0]>0?'slower':'unresolved-difference';
   }
   comparisons.push(c);
  }
  await fs.writeFile(root+`runs/${suite}-${kind}-timing.json`,JSON.stringify({protocol,startedAt,finishedAt:new Date().toISOString(),calibration,thresholds,samples,comparisons},null,2));
  console.log(JSON.stringify(comparisons));
 }
}finally{for(const runner of runners)await runner.close();await fs.rm(guard,{force:true});}

