import {readFile} from 'node:fs/promises';
import {performance} from 'node:perf_hooks';
import {createHash} from 'node:crypto';
import {Session} from 'node:inspector/promises';
import {writeFile} from 'node:fs/promises';
import {parseCssUrlMatches as regexp} from '../variants/baseline/lib/life-cycle/parse-css-urls.js';
import {parseCssUrlMatches as scanner} from '../variants/scanner/lib/life-cycle/parse-css-urls.js';
const mdn=await readFile(new URL('../fixtures/mdn-inline.css',import.meta.url),'utf8');
export const fixtures={
 'css-unique':{text:Array.from({length:512},(_,i)=>`.a${i}{background:url('../img/a-${i}.png')}`).join('\n'),iterations:64},
 'css-duplicates':{text:Array.from({length:2048},(_,i)=>`.a${i}{background:url('../img/a-${i%8}.png')}`).join('\n'),iterations:16},
 'mdn-inline-css':{text:mdn,iterations:128},
 'css-no-urls':{text:'.content{color:var(--text-primary);display:grid;gap:1rem;margin:auto;padding:0 1rem}\n'.repeat(512),iterations:64},
 'css-comments':{text:Array.from({length:512},(_,i)=>`/* url('ignored') */ .a${i}{background:url('../img/a-${i}.png')}`).join('\n'),iterations:64}
};
export const fixtureInfo=Object.fromEntries(Object.entries(fixtures).map(([name,x])=>[name,{bytes:Buffer.byteLength(x.text),iterations:x.iterations,urls:regexp(x.text).length,sha256:createHash('sha256').update(x.text).digest('hex')}]));
export function makeRunner(variant,pressure){
 const parse=variant===0?regexp:scanner;
 let sink=0;
 function work(key){
  const {text,iterations}=fixtures[key];let live=[],count=0;
  for(let repeat=0;repeat<iterations;repeat++){
   const matches=parse(text);count+=matches.length;
   for(const match of matches)sink=(sink+match.start+match.end+match.url.length)|0;
   if(pressure){live.push(new Array(32768).fill(123));if(live.length>8)live.shift();}
  }
  return count;
 }
 const hashes=Object.fromEntries(Object.entries(fixtures).map(([key,{text}])=>[key,createHash('sha256').update(JSON.stringify(parse(text))).digest('hex')]));
 return {
  async warm(key){for(let i=0;i<4;i++)work(key);},
  async sample(key){
   global.gc();const heapBefore=process.memoryUsage().heapUsed;
   const start=performance.now();const count=work(key);const totalMs=performance.now()-start;
   const memory=process.memoryUsage();global.gc();const retained=process.memoryUsage().heapUsed;
   return {case:key,totalMs,count,sha256:hashes[key],heapAfter:memory.heapUsed,heapBefore,retainedHeapDelta:retained-heapBefore,rss:memory.rss};
  },
  async profile(key,prefix){
   global.gc();const session=new Session();session.connect();
   await session.post('HeapProfiler.startSampling',{samplingInterval:4096,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});
   const count=work(key);const {profile}=await session.post('HeapProfiler.stopSampling');session.disconnect();
   await writeFile(prefix+'.heapprofile',JSON.stringify(profile));
   const stack=[profile.head];let bytes=0;while(stack.length){const n=stack.pop();bytes+=n.selfSize;stack.push(...n.children);}
   return {case:key,count,sha256:hashes[key],sampledBytes:bytes};
  },
  async close(){return sink;}
 };
}

