import {parseCssUrlMatches as baseline} from '../variants/baseline/lib/life-cycle/parse-css-urls.js';
import {parseCssUrlMatches as scanner} from '../variants/scanner/lib/life-cycle/parse-css-urls.js';
import {readFile, writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
let state=123456789;
const random=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};
const fragments=['url(foo)','url("url")',"url('a')",'url(  " " )','@import "import";','@import url(x);',"@IMPORT 'foo';",'URL(a b)','url(data:a,b)','/* url(skip) */','url("")','url()','url(\'x"y\')','url(  a  )',"@import x;",'url(foo(bar))','/*','*/','\n','\r','\u2028','\u00a0','x',"url('\\')",'@import"x";','url /*foo*/ (x)','url(/*foo*/x)','ur/*x*/l(a)','@import/*x*/ "a";','url(\'a\n b\')','url("a"b")','url(   )','@import url();','url(data:a\n,b)','url(data:a,b)','url(DATA:a,b)'];
let checked=0;
function verify(text){assert.deepEqual(scanner(text),baseline(text),text);checked++;}
for(const a of fragments)for(const b of fragments)verify(a+b);
for(let i=0;i<50000;i++){let text='';for(let k=0;k<8;k++)text+=fragments[Math.floor(random()*fragments.length)];verify(text);}
const html=await readFile(new URL('../fixtures/mdn.html',import.meta.url),'utf8');
const styles=[...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(x=>x[1]);
for(const text of styles)verify(text);
await writeFile(new URL('../fixtures/mdn-inline.css',import.meta.url),styles.join('\n'));
console.log(JSON.stringify({passed:true,checked,mdnStyles:styles.length,mdnCssBytes:Buffer.byteLength(styles.join('\n')),mdnCssUrls:baseline(styles.join('\n')).length}));

