import assert from 'node:assert/strict';
import {performance, PerformanceObserver} from 'node:perf_hooks';
import {promises as fs} from 'node:fs';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {Session} from 'node:inspector/promises';
import {probes} from './probes.mjs';
const [entry, mode = 'timing', profileFile] = process.argv.slice(2);
const api = await import(pathToFileURL(entry));
const {withCrawlContext} = await import(new URL('./crawl-context.js',pathToFileURL(entry)));
const {prepareHtmlParser} = await import(new URL('./cheerio.js',pathToFileURL(entry)));
await prepareHtmlParser();
const logger = {trace(){},debug(){},info(){},warn(){},error(){},isTraceEnabled(){return false;}};
const options=api.options.defaultDownloadOptions({...api.lifeCycle.defaultLifeCycle(),localRoot:'/out',initialUrl:[],createLogger:()=>logger});
const controller=new AbortController();const context={logger,signal:controller.signal};
const pipeline=new api.downloader.PipelineExecutorImpl(options,options.req,options,controller.signal);
const types=api.resource.ResourceType;
const fixtures={
 'css-unique':{type:types.Css,body:Array.from({length:512},(_,i)=>`.x${i}{background:url('../img/a-${i}.png')}`).join('\n'),count:512},
 'css-duplicates':{type:types.Css,body:Array.from({length:2048},(_,i)=>`.x${i}{background:url('../img/a-${i%8}.png')}`).join('\n'),count:8},
 'svg-links':{type:types.Svg,body:'<svg xmlns="http://www.w3.org/2000/svg">'+Array.from({length:512},(_,i)=>`<image href="../img/a-${i}.png"/>`).join('')+'</svg>',count:512},
 'html-links':{type:types.Html,body:'<html><body>'+Array.from({length:512},(_,i)=>`<img src="../img/a-${i}.png">`).join('')+'</body></html>',count:512},
 'link-chain':{type:types.Css,body:'',count:1024}
};
fixtures['css-siblings']={...fixtures['css-unique'],body:fixtures['css-unique'].body.replaceAll('../img/','')};
fixtures['html-siblings']={...fixtures['html-links'],body:fixtures['html-links'].body.replaceAll('../img/','')};
const selected=process.env.WSE_FOCUSED_CASES?.split(',')??Object.keys(fixtures);
const pressure=process.env.WSE_HEAP_PRESSURE==='1';
const guard=process.env.TMPDIR+'/focused-guard-'+process.pid;
await fs.writeFile(guard,Buffer.alloc(4096,17));for(let i=0;i<5;i++)await probes(guard);
let live=[],peak=0,gcEvents=[];
const observer=new PerformanceObserver(list=>gcEvents.push(...list.getEntries().map(x=>({kind:x.detail.kind,duration:x.duration}))));observer.observe({entryTypes:['gc']});
function churn(){if(pressure){live.push(new Array(32768).fill(123));if(live.length>8)live.shift();}peak=Math.max(peak,process.memoryUsage().heapUsed);}
async function workload(key,repeats=2){
 const fixture=fixtures[key];let checksum=createHash('sha256'),count=0;
 for(let round=0;round<repeats;round++){
  const url='https://example.test/docs/page.'+(fixture.type===types.Html?'html':fixture.type===types.Svg?'svg':'css');
  const parent={...api.resource.createResource({type:fixture.type,url,refUrl:url,depth:0,localRoot:'/out'}),body:fixture.body};
  let children=[];
  if(key==='link-chain'){
   for(let i=0;i<fixture.count;i++){
    children.push(await pipeline.createAndProcessResource('../img/a-'+i+'.png',types.Binary,1,null,parent));
    if(i%64===0)churn();
   }
  }else{
   await pipeline.processAfterDownload(parent,child=>children.push(...Array.isArray(child)?child:[child]));
  }
  assert.equal(children.length,fixture.count);
  for(const child of children){assert.ok(child.url.startsWith('https://example.test/'+(key.endsWith('siblings')?'docs/':'img/')+'a-'));checksum.update(child.url+'\0'+child.replacePath+'\n');count++;}
  checksum.update(parent.meta.doc?parent.meta.doc.html():parent.body);
  churn();
 }
 return {sha256:checksum.digest('hex'),count};
}
const results=[];
try{
 await withCrawlContext(context,async()=>{
  for(const key of selected){
   await workload(key);await workload(key);
   live=[];global.gc();await new Promise(r=>setImmediate(r));global.gc();
   if(mode==='profile'){
    const session=new Session();session.connect();await session.post('Profiler.enable');await session.post('Profiler.setSamplingInterval',{interval:250});await session.post('Profiler.start');
    await session.post('HeapProfiler.startSampling',{samplingInterval:4096,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});
    const value=await workload(key,4);
    const {profile:heap}=await session.post('HeapProfiler.stopSampling');const {profile:cpu}=await session.post('Profiler.stop');session.disconnect();
    await fs.writeFile(profileFile+'-'+key+'.heapprofile',JSON.stringify(heap));await fs.writeFile(profileFile+'-'+key+'.cpuprofile',JSON.stringify(cpu));results.push({case:key,...value});
   }else{
    for(let sample=0;sample<2;sample++){
     live=[];global.gc();await new Promise(r=>setImmediate(r));const before=process.memoryUsage();peak=before.heapUsed;gcEvents=[];
     const noiseBefore=await probes(guard);const cpu=process.cpuUsage();const start=performance.now();
     const value=await workload(key);const totalMs=performance.now()-start;const cpuUsed=process.cpuUsage(cpu);const end=process.memoryUsage();
     const noiseAfter=await probes(guard);await new Promise(r=>setImmediate(r));const events=gcEvents;
     live=[];global.gc();await new Promise(r=>setImmediate(r));global.gc();const retained=process.memoryUsage();
     results.push({case:key,sample,totalMs,cpuMs:(cpuUsed.user+cpuUsed.system)/1000,noiseBefore,noiseAfter,...value,
      heapPeakObserved:peak,heapBefore:before.heapUsed,heapAfter:end.heapUsed,retainedHeapDelta:retained.heapUsed-before.heapUsed,
      rss:end.rss,external:end.external,arrayBuffers:end.arrayBuffers,gcCount:events.length,gcMs:events.reduce((a,b)=>a+b.duration,0)});
    }
   }
  }
 });
 console.log(JSON.stringify({node:process.version,pressure,mode,maxRssKiB:process.resourceUsage().maxRSS,results}));
}finally{observer.disconnect();await fs.rm(guard,{force:true});}

