import {parseCssUrlMatches as regexpMatches} from './parse-css-regexp.js';
import type {CssUrlMatch} from './parse-css-regexp.js';
export type {CssUrlMatch} from './parse-css-regexp.js';

const unusualSpace = /\s/;
function space(code: number): boolean {
  return code === 32 || code >= 9 && code <= 13 ||
    code > 127 && unusualSpace.test(String.fromCharCode(code));
}
function lineBreak(text: string, start: number, end: number): boolean {
  for (let i = start; i < end; i++) {
    const code = text.charCodeAt(i);
    if (code === 10 || code === 13 || code === 0x2028 || code === 0x2029) return true;
  }
  return false;
}
function isUrl(text: string, index: number): boolean {
  return (text.charCodeAt(index) | 32) === 117 &&
    (text.charCodeAt(index + 1) | 32) === 114 && (text.charCodeAt(index + 2) | 32) === 108;
}

// Specialized extractor for the existing grammar, not a CSS parser. Irregular
// tokens fall back for the whole input, retaining legacy matching and offsets.
export function parseCssUrlMatches(text: string): CssUrlMatch[] {
  const matches: CssUrlMatch[] = [];
  let comment = text.indexOf('/*');
  let lower = text.indexOf('u');
  let upper = text.indexOf('U');
  let atSign = text.indexOf('@');
  for (let i = 0; i < text.length;) {
    if (lower !== -1 && lower < i) lower = text.indexOf('u', i);
    if (upper !== -1 && upper < i) upper = text.indexOf('U', i);
    if (atSign !== -1 && atSign < i) atSign = text.indexOf('@', i);
